// Shared brand-styled react-select config for profile forms (location/country pickers).
import { StylesConfig } from "react-select";

export type Option = { value: string | number; label: string };

export const brandSelectStyles: StylesConfig<Option, false> = {
  control: (base, state) => ({
    ...base,
    minHeight: 42,
    borderRadius: 8,
    fontSize: 14,
    backgroundColor: "#fff",
    borderColor: state.isFocused ? "#854ec9" : "#d6d2de",
    boxShadow: state.isFocused ? "0 0 0 3px rgba(133,78,201,0.12)" : "none",
    ":hover": { borderColor: "#854ec9" },
  }),
  valueContainer: (base) => ({ ...base, padding: "2px 10px" }),
  placeholder: (base) => ({ ...base, color: "#9b95a8" }),
  menu: (base) => ({
    ...base,
    borderRadius: 10,
    overflow: "hidden",
    boxShadow: "0 14px 34px rgba(20,16,28,0.14)",
    zIndex: 30,
  }),
  option: (base, state) => ({
    ...base,
    fontSize: 14,
    color: state.isSelected ? "#fff" : "#14101c",
    backgroundColor: state.isSelected ? "#854ec9" : state.isFocused ? "#f6f4fa" : "#fff",
    ":active": { backgroundColor: "#854ec9", color: "#fff" },
  }),
};
