import React from "react";
import Select from "react-select";
import { labelCls, inputCls } from "@/components/profile-page/fieldStyles";
import { brandSelectStyles, Option } from "./selectStyles";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { IconDefinition } from "@fortawesome/fontawesome-svg-core";
import {
  faIdCard,
  faPassport,
  faAddressBook,
  faShareNodes,
  faLock,
} from "@fortawesome/free-solid-svg-icons";

const req = <span className="tw-text-[#b23838]">*</span>;

function Section({
  icon,
  title,
  children,
}: {
  icon: IconDefinition;
  title: string;
  children: React.ReactNode;
}) {
  return (
    <div className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-6 tw-shadow-[0_8px_30px_rgba(20,16,28,0.05)]">
      <div className="tw-mb-5 tw-flex tw-items-center tw-gap-3">
        <span className="tw-flex tw-h-9 tw-w-9 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#f4eefc] tw-text-[#854ec9]">
          <FontAwesomeIcon icon={icon} />
        </span>
        <h3 className="tw-m-0 tw-text-base tw-font-bold tw-uppercase tw-tracking-wide tw-text-[#14101c]">
          {title}
        </h3>
      </div>
      {children}
    </div>
  );
}

export default function PersonalInformationForm({ userData, setUserData, locations }: { userData: any; setUserData: any; locations: any }) {
  // Ana site yalnız müşteri — operatöre özel alanlar (Management Title) business'ta.
  const isOperator = false;

  const countryOptions: Option[] = [...locations]
    .sort((a: { name: number }, b: { name: number }) => {
      if (a.name < b.name) return -1;
      if (a.name > b.name) return 1;
      return 0;
    })
    .map((item: any) => ({ value: item.id, label: item.name }));

  const selectedCountry =
    countryOptions.find((o) => String(o.value) === String(userData.countryId)) ?? null;

  const grid = "tw-grid tw-grid-cols-1 tw-gap-5 md:tw-grid-cols-2";

  return (
    <div className="tw-flex tw-flex-col tw-gap-5">
      {/* Identity */}
      <Section icon={faIdCard} title="Identity">
        <div className={grid}>
          <div>
            <label htmlFor="nameInput" className={labelCls}>Name {req}</label>
            <input
              type="text"
              className={inputCls}
              id="nameInput"
              value={userData.firstName}
              onChange={(event: any) => setUserData({ ...userData, firstName: event.target.value })}
            />
          </div>
          <div>
            <label htmlFor="surnameInput" className={labelCls}>Surname {req}</label>
            <input
              type="text"
              className={inputCls}
              id="surnameInput"
              value={userData.lastName}
              onChange={(event: any) => setUserData({ ...userData, lastName: event.target.value })}
            />
          </div>
          <div>
            <label htmlFor="dobInput" className={labelCls}>Date of Birth {req}</label>
            <input
              type="date"
              className={inputCls}
              autoComplete="off"
              value={userData.dob}
              id="dobInput"
              onChange={(event: any) => setUserData({ ...userData, dob: event.target.value })}
            />
          </div>
          <div>
            <label htmlFor="gender" className={labelCls}>Gender {req}</label>
            <select
              className={inputCls}
              value={userData.gender ?? ""}
              id="gender"
              onChange={(event: any) => setUserData({ ...userData, gender: event.target.value })}
            >
              <option value="" disabled>Select Gender</option>
              <option value="male">Male</option>
              <option value="female">Female</option>
              <option value="other">Other</option>
            </select>
          </div>

          {isOperator && (
            <div className="md:tw-col-span-2">
              <label htmlFor="management" className={labelCls}>Management Title</label>
              <select
                className={inputCls}
                value={userData.managementTitle ?? ""}
                id="management"
                onChange={(event: any) => setUserData({ ...userData, managementTitle: event.target.value })}
              >
                <option value="" disabled>Select Title</option>
                <option value="ceo">CEO</option>
                <option value="general_manager">General Manager</option>
                <option value="travel_consultant">Travel Consultant</option>
                <option value="operations_manager">Operations Manager</option>
                <option value="booking_coordinator">Booking Coordinator / Customer Service Representative</option>
                <option value="sales_marketing_specialist">Sales &amp; Marketing Specialist</option>
                <option value="finance_admin_assistant">Finance/Admin Assistant</option>
                <option value="event_coordinator">Event Coordinator</option>
                <option value="administrative_support">Administrative Support</option>
              </select>
            </div>
          )}
        </div>
      </Section>

      {/* Passport — not needed for operators */}
      {!isOperator && (
        <Section icon={faPassport} title="Passport Details">
          <div className={grid}>
            <div>
              <label htmlFor="passport" className={labelCls}>Passport Number</label>
              <input
                type="text"
                className={inputCls}
                autoComplete="off"
                value={userData.passportNumber}
                id="passport"
                onChange={(event: any) => setUserData({ ...userData, passportNumber: event.target.value })}
              />
            </div>
            <div>
              <label htmlFor="passportDate" className={labelCls}>Passport Issue Date</label>
              <input
                type="date"
                className={inputCls}
                autoComplete="off"
                value={userData.passportIssuedAt}
                id="passportDate"
                onChange={(event: any) => setUserData({ ...userData, passportIssuedAt: event.target.value })}
              />
            </div>
            <div>
              <label htmlFor="passportExpiration" className={labelCls}>Passport Expiration Date</label>
              <input
                type="date"
                className={inputCls}
                autoComplete="off"
                value={userData.passportExpiresAt}
                id="passportExpiration"
                onChange={(event: any) => setUserData({ ...userData, passportExpiresAt: event.target.value })}
              />
            </div>
          </div>
        </Section>
      )}

      {/* Contact & Address */}
      <Section icon={faAddressBook} title="Contact and Address">
        <div className={grid}>
          <div>
            <label htmlFor="emailInput" className={labelCls}>Email address {req}</label>
            <input
              type="email"
              className={inputCls}
              autoComplete="off"
              value={userData.email}
              id="emailInput"
              onChange={(event: any) => setUserData({ ...userData, email: event.target.value })}
            />
          </div>
          <div>
            <label htmlFor="phone" className={labelCls}>Phone Number</label>
            <input
              type="tel"
              className={inputCls}
              autoComplete="off"
              value={userData.phone}
              id="phone"
              onChange={(event: any) => setUserData({ ...userData, phone: event.target.value })}
            />
          </div>
          <div>
            <label htmlFor="customerNationality" className={labelCls}>Country</label>
            <Select<Option>
              instanceId="profile-country"
              inputId="customerNationality"
              options={countryOptions}
              value={selectedCountry}
              onChange={(opt) => setUserData({ ...userData, countryId: opt ? String(opt.value) : "" })}
              placeholder="Search a country..."
              isClearable
              styles={brandSelectStyles}
            />
          </div>
          <div>
            <label htmlFor="address" className={labelCls}>Address</label>
            <input
              type="text"
              className={inputCls}
              autoComplete="off"
              value={userData.address}
              id="address"
              onChange={(event: any) => setUserData({ ...userData, address: event.target.value })}
            />
          </div>
        </div>
      </Section>

      {/* Social Medias — not needed for operators */}
      {!isOperator && (
        <Section icon={faShareNodes} title="Social Medias">
          <div className={grid}>
            <div>
              <label htmlFor="google" className={labelCls}>Google</label>
              <input
                type="text"
                className={inputCls}
                autoComplete="off"
                value={userData.google}
                id="google"
                onChange={(event: any) => setUserData({ ...userData, google: event.target.value })}
              />
            </div>
            <div>
              <label htmlFor="facebook" className={labelCls}>Facebook</label>
              <input
                type="text"
                className={inputCls}
                autoComplete="off"
                value={userData.facebook}
                id="facebook"
                onChange={(event: any) => setUserData({ ...userData, facebook: event.target.value })}
              />
            </div>
          </div>
        </Section>
      )}

      {/* Security */}
      <Section icon={faLock} title="Security Information">
        <p className="tw-mb-4 tw-mt-0 tw-text-sm tw-text-[#6b6577]">
          If you do not intend to change your password, please keep these fields empty.
        </p>
        <div className="tw-flex tw-flex-col tw-gap-5">
          <div className="md:tw-max-w-[calc(50%-0.625rem)]">
            <label htmlFor="currentPasswordInput" className={labelCls}>Current Password</label>
            <input
              type="password"
              className={inputCls}
              id="currentPasswordInput"
              value={userData.currentPassword}
              autoComplete="new-password"
              onChange={(event: any) => setUserData({ ...userData, currentPassword: event.target.value })}
            />
          </div>
          <div className={grid}>
            <div>
              <label htmlFor="newPasswordInput" className={labelCls}>New Password</label>
              <input
                type="password"
                className={inputCls}
                id="newPasswordInput"
                value={userData.newPassword}
                autoComplete="new-password"
                onChange={(event: any) => setUserData({ ...userData, newPassword: event.target.value })}
              />
            </div>
            <div>
              <label htmlFor="passwordAgainInput" className={labelCls}>New Password Again</label>
              <input
                type="password"
                className={inputCls}
                id="passwordAgainInput"
                value={userData.newPasswordAgain}
                onChange={(event: any) => setUserData({ ...userData, newPasswordAgain: event.target.value })}
              />
            </div>
          </div>
        </div>
      </Section>
    </div>
  );
}
