
"use client";
import React, {useEffect, useState} from "react";
import {getCookie, hasCookie} from "cookies-next";
import getUserDetail from "@/services/auth/userDetail";
import Breadcrumb from "@/components/header/breadcrumb";
import postProfileUpdate, {postProfilePhotoUpdate} from "@/services/auth/profile/updateProfile";
import Menu from "./menu";
import Image from "next/image";
import PersonalInformationForm from "@/components/profile-page/personal-information-form";
import getLocations from "@/services/locations";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCamera } from "@fortawesome/free-solid-svg-icons";

const allowedTypes = [
  'image/jpeg',
  'image/png',
  'image/webp',
];

export default function PersonalInformation() {
  const [userLoading, setUserLoading] = useState(true);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [submitStatus, setSubmitStatus] = useState("");
  const [locations, setLocations] = useState([])
  const [image, setImage] = useState(null);
  const [createObjectURL, setCreateObjectURL] = useState(null);

  const [user, setUser] = useState({
    name: "",
    email: "",
  });
  const [userData, setUserData] = useState({
    name: "",
    firstName: "",
    lastName: "",
    email: "",
    title: "",
    dob: "",
    phone: "",
    address: "",
    gender: "",
    google: "",
    facebook: "",
    image: "",
    passportNumber: "",
    passportIssuedAt: "",
    passportExpiresAt: "",
    managementTitle: "",
    currentPassword: "",
    newPassword: "",
    newPasswordAgain: "",
    countryId: "",
    travelStyles: [],
    lodgings: [],
    activities: [],
    categories: [],
  });

  const fetchLocations = async () => {
    await getLocations().then((res) => {
      setLocations(res);
    });
  };

  useEffect(() => {
    fetchLocations();
  }, []);

  const updateSubmit = async () => {
    if (userData.email && userData.firstName && userData.lastName) {
      if (
          userData.currentPassword != "" &&
          userData.newPassword != "" &&
          userData.newPassword !== userData.newPasswordAgain
      ) {
        setErrorMessage("Password and confirmation do not match.");
        setSubmitStatus("error");
      } else {
        if (
            userData.currentPassword != "" &&
            userData.newPassword !== userData.newPasswordAgain &&
            userData.newPassword.length < 6
        ) {
          setErrorMessage("Your password must be at least 6 characters.");
        } else {
          setSubmitStatus("");
          setErrorMessage("");

          try {
            setLoading(true);

            const res = await postProfileUpdate({
              requestData: userData,
              token: getCookie("auth-token"),
            });

            if ("success" in res) {
              if (res.success) {
                setErrorMessage("");
                setSubmitStatus("success");

                setUserData({
                  ...userData,
                  currentPassword: "",
                  newPassword: "",
                  newPasswordAgain: "",
                });
              } else {
                setErrorMessage(res.message);
                setSubmitStatus("error");
              }
            } else {
              setErrorMessage(res.errors[Object.keys(res.errors)[0]][0]);
              setSubmitStatus("error");
            }
          } catch (error: any) {
            setSubmitStatus("error");
            setErrorMessage(
                "The e-mail address is registered in our system. Please provide any other information."
            );
          }
          setLoading(false);
        }
      }
    } else {
      setErrorMessage("Please fill in the required fields.");
      setSubmitStatus("error");
    }
  };

  const fetchUserDetail = async () => {
     return await getUserDetail({token: getCookie("auth-token")});
  };

  useEffect(() => {
    if (hasCookie("auth-token")) {
      try {
        fetchUserDetail().then((res: any) => {
          setUserData({
            name: res.name,
            firstName: res.first_name,
            lastName: res.last_name,
            title: res.title,
            dob: res.dob,
            image: res.avatar,
            gender: res.gender,
            phone: res.phone,
            address: res.address,
            facebook: res.facebook,
            google: res.google,
            passportNumber: res.passport,
            passportIssuedAt: res.passport_issued_at,
            passportExpiresAt: res.passport_expires_at,
            managementTitle: res.management_title,
            email: res.email,
            currentPassword: "",
            newPassword: "",
            newPasswordAgain: "",
            countryId: res.country_id,
            travelStyles: res.meta.preffered_travel_styles,
            lodgings: res.meta.preffer_lodgings,
            activities: res.meta.activities,
            categories: res.meta.categories,
          });
          setUser({ name: res.first_name + " " + res.last_name, email: res.email });
          setUserLoading(false);
        });
      } catch (e) {}
    } else {
      setUserLoading(false);
    }
  }, []);

  const handleBoxClick = () => {
    // @ts-ignore
    document.getElementById('fileInput').click();
  };

  const uploadToClient = (event: any) => {
    if (event.target.files && event.target.files[0]) {
      const file = event.target.files[0];

      const fileSizeInKB = file.size / 1024;

      if (!allowedTypes.includes(event.target.files[0].type)) {
        setSubmitStatus("error");
        setErrorMessage("Invalid file type.");
        return;
      }
      setSubmitStatus("");

      setImage(file);
      setUserData(prevState => ({
        ...prevState,
        image: file
      }))

      // @ts-ignore
      setCreateObjectURL(URL.createObjectURL(file));
    }
  };

  const uploadPhotoToServer = async () => {
    try {
      setLoading(true);

      const res = await postProfilePhotoUpdate({
        file: image,
        token: getCookie("auth-token"),
      });

      if (res.data.success) {
        setErrorMessage("");
        setSubmitStatus("success");
        setImage(null);

      } else {
        setErrorMessage(res.message);
        setSubmitStatus("error");
      }
    } catch (error: any) {
      setSubmitStatus("error");
      setErrorMessage(
          "An error occurred while uploading the photo"
      );
    }
    setLoading(false);
  }

  const showProfileHeader = !!getCookie("user-role");

  return (
      <main className="tw-font-display">
        <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6">
          <Breadcrumb items={[{pageTitle: "Profile", pageUrl: "/profile"}]}/>
          <h1 className="tw-mt-2 tw-mb-5 tw-text-[clamp(22px,2.6vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
            Personal Information
          </h1>

          <div className="tw-grid tw-grid-cols-1 tw-gap-6 md:tw-grid-cols-[260px_minmax(0,1fr)]">
            <div>
              <Menu/>
            </div>

            <div>
              {userLoading && (
                  <div className="tw-flex tw-flex-col tw-items-center tw-gap-3 tw-py-16 tw-text-[#5d556c]">
                    <span className="tw-inline-block tw-h-8 tw-w-8 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
                    <p className="tw-m-0 tw-text-sm">Loading. Please wait.</p>
                  </div>
              )}

              {!userLoading && (
                  <div className="tw-flex tw-flex-col tw-gap-5">
                    {/* Hidden file input for avatar */}
                    <input
                        type="file"
                        id="fileInput"
                        name="file"
                        className="tw-hidden"
                        onChange={uploadToClient}
                    />

                    {showProfileHeader && (
                        <div className="tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_8px_30px_rgba(20,16,28,0.05)]">
                          <div className="tw-h-28 tw-bg-gradient-to-r tw-from-[#854ec9] tw-to-[#6a3da4]" />
                          <div className="tw-flex tw-flex-col tw-items-center tw-gap-4 tw-px-6 tw-pb-6 sm:tw-flex-row sm:tw-items-end">
                            <div className="tw--mt-16 tw-relative tw-shrink-0">
                              <Image
                                  src={createObjectURL ?? (userData.image ?? "/images/avatar-2.png")}
                                  alt="Profile Picture"
                                  width={110}
                                  height={110}
                                  quality={100}
                                  className="tw-h-[110px] tw-w-[110px] tw-rounded-full tw-bg-white tw-object-cover tw-ring-4 tw-ring-white tw-shadow-[0_10px_30px_rgba(20,16,28,0.18)]"
                              />
                              <button
                                  type="button"
                                  onClick={handleBoxClick}
                                  aria-label="Change photo"
                                  className="tw-absolute tw-bottom-1 tw-right-1 tw-flex tw-h-9 tw-w-9 tw-cursor-pointer tw-items-center tw-justify-center tw-rounded-full tw-border-2 tw-border-solid tw-border-white tw-bg-[#854ec9] tw-text-white tw-transition-colors hover:tw-bg-[#6a3da4]"
                              >
                                <FontAwesomeIcon icon={faCamera} className="tw-text-xs" />
                              </button>
                            </div>
                            <div className="tw-flex tw-flex-col tw-items-center tw-pb-1 sm:tw-items-start">
                              <h2 className="tw-m-0 tw-text-xl tw-font-bold tw-tracking-tight tw-text-[#14101c]">
                                {user.name}
                              </h2>
                              {user.email && (
                                  <p className="tw-m-0 tw-text-sm tw-text-[#6b6577]">{user.email}</p>
                              )}
                              {image && (
                                  <button
                                      type="button"
                                      onClick={uploadPhotoToServer}
                                      disabled={loading}
                                      className="tw-mt-3 tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-4 tw-py-2 tw-text-xs tw-font-semibold tw-text-white tw-transition-colors hover:tw-bg-[#6a3da4] disabled:tw-opacity-70"
                                  >
                                    {loading && (
                                        <span className="tw-inline-block tw-h-3.5 tw-w-3.5 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent" />
                                    )}
                                    Save Photo
                                  </button>
                              )}
                            </div>
                          </div>
                        </div>
                    )}

                    {submitStatus == "error" && (
                        <div className="tw-rounded-xl tw-border tw-border-solid tw-border-[#f3c2c2] tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-sm tw-text-[#b23838]">
                          {errorMessage}
                        </div>
                    )}
                    {submitStatus == "success" && (
                        <div className="tw-rounded-xl tw-border tw-border-solid tw-border-[#bfe6cd] tw-bg-[#eafaf0] tw-px-4 tw-py-3 tw-text-sm tw-text-[#1f8a4c]">
                          Your information has been saved successfully.
                        </div>
                    )}

                    {/*profile detail form*/}
                    <PersonalInformationForm
                        userData={userData}
                        setUserData={setUserData}
                        locations={locations}
                    />

                    <div>
                      {loading ? (
                          <button
                              type="button"
                              disabled
                              className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-6 tw-py-3 tw-text-sm tw-font-semibold tw-text-white tw-opacity-70"
                          >
                            <span className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent" />
                            Loading...
                          </button>
                      ) : (
                          <button
                              type="button"
                              onClick={updateSubmit}
                              className="tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-8 tw-py-3 tw-text-sm tw-font-semibold tw-text-white tw-transition-colors hover:tw-bg-[#6a3da4]"
                          >
                            Save
                          </button>
                      )}
                    </div>
                  </div>
              )}
            </div>
          </div>
        </div>
      </main>
  );
}
